package com.bank.portal.web; import com.bank.portal.service.BankingService; import com.bank.portal.web.ApiDtos.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/payments") @RequiredArgsConstructor public class PaymentController {private final BankingService service;@PostMapping public TransactionView pay(@Valid @RequestBody PaymentRequest r,Authentication a){boolean staff=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_STAFF"));return service.pay(r,a.getName(),staff);}}
